25	// so plugin LOG_DEBUG messages respect the application's log level.
26	extern "C" EDGELLM_PLUGIN_EXPORT bool initEdgellmPlugins(void* logger, char const* /*libNamespace*/)
27	{
28	    if (logger)
29	    {
30	        auto* appLogger = dynamic_cast<trt_edgellm::logger::EdgeLLMLogger*>(static_cast<nvinfer1::ILogger*>(logger));
31	        if (appLogger)
32	        {
33	            trt_edgellm::gLogger.setLevel(appLogger->getLevel());
34	        }
35	    }
36	    return true;
37	}
